// Procedure drawGraph for drawing function graph in full window
// with Y-axis scaling
// Redraws graph when window size changes
uses GraphABC;

function f(x: real) := x*sin(x)*exp(-0.1*x);

// l (logical) - logical coordinates
// s (screen) - physical coordinates
procedure drawGraph(x1,x2: real; f: real -> real);
 var
  xl0,wl,yl0,hl: real;
  xs0,ws,ys0,hs: integer;

 function LtoSx(xl: real) := round(ws/wl*(xl-xl0)+xs0);
 function LtoSy(yl: real) := round(hs/hl*(yl-yl0)+ys0);
 function StoLx(xs: integer) := wl/ws*(xs-xs0)+xl0;

begin // drawGraph
  xs0 := 0;
  ys0 := WindowHeight-1;
  ws := WindowWidth;
  hs := WindowHeight-1;

  xl0 := x1;
  wl := x2-x1;

  var yi: array of real;
  SetLength(yi,ws+1);

  var min := real.MaxValue;
  var max := real.MinValue;
  for var xi:=0 to ws do
  begin
    yi[xi] := f(StoLx(xi+xs0));
    if yi[xi]<min then 
      min := yi[xi];
    if yi[xi]>max then 
      max := yi[xi];
  end;

  yl0 := min;
  hl := -(max-min);

  // Draw coordinate system axes
  Line(0,LtoSy(0),ws,LtoSy(0));
  Line(LtoSx(0),0,LtoSx(0),hs);

  Pen.Color := clBlue;
  MoveTo(xs0,LtoSy(yi[0]));
  for var xi:=xs0+1 to xs0+ws do
    LineTo(xi,LtoSy(yi[xi-xs0]));
end;

procedure Resize;
begin
  ClearWindow;
  drawGraph(0,60,f);
  Redraw;
end;

begin
  LockDrawing;
  SetWindowCaption('Function graph: scaling');
  drawGraph(0,60,f);
  Redraw;
  OnResize := Resize;
end.

// Example from KuMir/PMir package
// Published almost without changes
// Precious as memory :)
Uses GraphABC;

var Xmin,Xmax,Xstep: real;
    Ymin,Ymax,Ystep,asp: real;
    dx: integer;

function f(x,y:real): integer;
var r: real;
begin
  r := x*x+y*y+1;
  f := round(5*asp*(cos(r)/r+0.1))
end;

procedure gr(N : integer);
var X,Y: real; 
    i,j,k,Z0,dy: integer; 
    pred: array [1..100] of integer;
    jj,maxX,maxY: integer;
begin
  Xmin := -4;
  Xmax := 4;
  Ymin := -3;
  Ymax := 3;
  maxX := 600;
  maxY := 400;
  Xstep := dx*(Xmax-Xmin)/maxX; 
  X := Xmin;
  Ystep := (Ymax-Ymin)/N;     
  Y := Ymin;
  dy := maxY div N div 2;        
  asp := maxY/8;
  for i := 1 to N do
  begin
    pred[i] := maxY-i*dy-f(X,Y);
    Y := Y + Ystep
  end;
  for jj := 1 to maxX div dx do 
  begin
    j := jj*dx;
    X := X + Xstep;
    Y := Ymin; Z0 := maxY;
    for i := 1 to N do 
    begin
      k := maxY-i*dy-f(X,Y);
      if k<Z0 then
      begin
        Line(j-dx,pred[i],j,k);
        Z0 := k
      end;
      pred[i] := Z0;
      Y := Y+Ystep
    end;
  end;
end;

begin
  SetWindowCaption('Function graph of two variables');
  SetWindowSize(600,400);
  dx := 2; { X-axis resolution }
  gr(100); { number of lines by Y <= MaxN }
end.

